//! rlibc-x1: Minimal no_std libc for Linux x86_64
//!
//! Provides runtime support for #![no_std] Rust binaries.

#![no_std]

use core::arch::asm;

// Syscall numbers for x86_64 Linux
const SYS_WRITE: u64 = 1;
const SYS_EXIT: u64 = 60;
const SYS_BRK: u64 = 12;

/// Raw syscall wrappers
#[inline(always)]
unsafe fn syscall1(n: u64, a1: u64) -> u64 {
    let ret: u64;
    asm!(
        "syscall",
        in("rax") n,
        in("rdi") a1,
        lateout("rax") ret,
        lateout("rcx") _,
        lateout("r11") _,
        options(nostack)
    );
    ret
}

#[inline(always)]
unsafe fn syscall3(n: u64, a1: u64, a2: u64, a3: u64) -> u64 {
    let ret: u64;
    asm!(
        "syscall",
        in("rax") n,
        in("rdi") a1,
        in("rsi") a2,
        in("rdx") a3,
        lateout("rax") ret,
        lateout("rcx") _,
        lateout("r11") _,
        options(nostack)
    );
    ret
}

/// Exit the program with the given status code
#[inline(always)]
pub fn exit(status: i32) -> ! {
    unsafe {
        syscall1(SYS_EXIT, status as u64);
    }
    // This should never be reached, but required for -> !
    loop {}
}

/// Write to a file descriptor
#[inline(always)]
pub fn write(fd: i32, buf: &[u8]) -> isize {
    unsafe { syscall3(SYS_WRITE, fd as u64, buf.as_ptr() as u64, buf.len() as u64) as isize }
}

/// Print a string to stdout
#[inline(always)]
pub fn print(s: &str) {
    write(1, s.as_bytes());
}

/// Print a string to stdout with newline
#[inline(always)]
pub fn println(s: &str) {
    print(s);
    write(1, b"\n");
}

// Simple bump allocator using brk
static mut HEAP_START: usize = 0;
static mut HEAP_END: usize = 0;
static mut HEAP_CURRENT: usize = 0;

unsafe fn brk(addr: usize) -> usize {
    syscall1(SYS_BRK, addr as u64) as usize
}

fn init_heap() {
    unsafe {
        if HEAP_START == 0 {
            HEAP_START = brk(0);
            HEAP_END = HEAP_START;
            HEAP_CURRENT = HEAP_START;
        }
    }
}

/// Allocate memory (simple bump allocator)
pub fn malloc(size: usize) -> *mut u8 {
    init_heap();

    let align = 16;
    unsafe {
        let aligned = (HEAP_CURRENT + align - 1) & !(align - 1);
        let new_current = aligned + size;

        if new_current > HEAP_END {
            let new_end = brk(new_current);
            if new_end < new_current {
                return core::ptr::null_mut();
            }
            HEAP_END = new_end;
        }

        HEAP_CURRENT = new_current;
        aligned as *mut u8
    }
}

/// Free memory (no-op in bump allocator)
pub fn free(_ptr: *mut u8) {
    // Bump allocator doesn't free
}

// Entry point - called by linker
#[unsafe(no_mangle)]
pub unsafe extern "C" fn _start() -> ! {
    // Call the user's main function
    extern "Rust" {
        fn main();
    }
    _start_rust();
}

#[inline(always)]
unsafe fn _start_rust() -> ! {
    extern "Rust" {
        fn main();
    }
    main();
    exit(0)
}

// Panic handler for no_std
#[panic_handler]
fn panic(_info: &core::panic::PanicInfo) -> ! {
    println("PANIC!");
    exit(101)
}

