//! rlibc-x2: Libc replacement for Rust std apps on Linux x86_64
//!
//! This library provides libc functionality for apps using Rust's std library,
//! allowing them to be built without linking against glibc.

#![no_std]

mod errno;
mod io;
mod memory;
mod process;
mod signal;
mod syscall;
mod thread;

pub use errno::*;
pub use io::*;
pub use memory::*;
pub use process::*;
pub use signal::*;
pub use syscall::*;
pub use thread::*;

/// Macro for creating stub functions that print a message and exit
#[macro_export]
macro_rules! stub {
    ($name:ident) => {
        #[unsafe(no_mangle)]
        pub extern "C" fn $name() {
            // Print stub message
            let msg = concat!("STUB: ", stringify!($name), "\n");
            unsafe {
                $crate::write(2, msg.as_ptr(), msg.len());
                $crate::exit(99);
            }
        }
    };
    ($name:ident, $ret:expr) => {
        #[unsafe(no_mangle)]
        pub extern "C" fn $name() -> isize {
            // Print stub message
            let msg = concat!("STUB: ", stringify!($name), "\n");
            unsafe {
                $crate::write(2, msg.as_ptr(), msg.len());
            }
            $ret
        }
    };
}

// Stubs for functions that Rust std might call but we don't implement
stub!(getenv, 0);
stub!(setenv, -1);
stub!(unsetenv, -1);

